+        decideWipLabel: decideWipLabel,
+        decideSmTriggerLabel: decideSmTriggerLabel,
+        resolveFeatureSummary: resolveFeatureSummary,
+        needsVerdictPrefix: needsVerdictPrefix,
+        prependVerdictIfNeeded: prependVerdictIfNeeded,
